insert into v2.skills (code, subject, grade, strand, topic, text, short, prereqs, provisional, position) values
  ('T1.STN.DEM-DOC-VIET', 'toan', 1, 'SO-PHEP-TINH', 'Số tự nhiên', 'Đếm, đọc, viết được các số trong phạm vi 10; trong phạm vi 20; trong phạm vi 100.', 'Đếm, đọc, viết số đến 100', '{}'::text[], false, 0),
  ('T1.STN.CHUC-DON-VI', 'toan', 1, 'SO-PHEP-TINH', 'Số tự nhiên', 'Nhận biết được chục và đơn vị, số tròn chục.', 'Chục và đơn vị', array['T1.STN.DEM-DOC-VIET']::text[], false, 1),
