  ('T1.PT.HAI-DAU-TINH', 'toan', 1, 'SO-PHEP-TINH', 'Các phép tính với số tự nhiên', 'Làm quen với việc thực hiện tính toán trong trường hợp có hai dấu phép tính cộng, trừ (theo thứ tự từ trái sang phải).', 'Tính có hai dấu phép tính', array['T1.PT.CONG-TRU-KHONG-NHO']::text[], false, 5),
