  ('T1.HH.VI-TRI', 'toan', 1, 'HINH-DO-LUONG', 'Hình học trực quan', 'Nhận biết được vị trí, định hướng trong không gian: trên – dưới, phải – trái, trước – sau, ở giữa.', 'Trên dưới, phải trái, trước sau', '{}'::text[], false, 10),
  ('T1.HH.HINH-PHANG', 'toan', 1, 'HINH-DO-LUONG', 'Hình học trực quan', 'Nhận dạng được hình vuông, hình tròn, hình tam giác, hình chữ nhật thông qua việc sử dụng bộ đồ dùng học tập cá nhân hoặc vật thật.', 'Nhận dạng hình phẳng', '{}'::text[], false, 11),
  ('T1.HH.KHOI', 'toan', 1, 'HINH-DO-LUONG', 'Hình học trực quan', 'Nhận dạng được khối lập phương, khối hộp chữ nhật thông qua việc sử dụng bộ đồ dùng học tập cá nhân hoặc vật thật.', 'Khối lập phương, khối hộp', '{}'::text[], false, 12),
