  ('T3.DL.CHU-VI', 'toan', 3, 'HINH-DO-LUONG', 'Đo lường', 'Tính được chu vi của hình tam giác, hình tứ giác, hình chữ nhật, hình vuông khi biết độ dài các cạnh.', 'Chu vi các hình', array['T3.HH.YEU-TO-HINH', 'T2.DL.GAP-KHUC']::text[], false, 109),
  ('T3.DL.DIEN-TICH-HCN', 'toan', 3, 'HINH-DO-LUONG', 'Đo lường', 'Tính được diện tích hình chữ nhật, hình vuông.', 'Diện tích chữ nhật, vuông', array['T3.DL.CM2', 'T3.PT.NHAN-1-CS']::text[], false, 110),
  ('T3.DL.UOC-LUONG', 'toan', 3, 'HINH-DO-LUONG', 'Đo lường', 'Thực hiện được việc ước lượng các kết quả đo lường trong một số trường hợp đơn giản (ví dụ: cân nặng của một con gà khoảng 2kg,...).', 'Ước lượng kết quả đo', array['T2.DL.UOC-LUONG']::text[], false, 111),
