  ('T3.TK.THU-THAP', 'toan', 3, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Nhận biết được cách thu thập, phân loại, ghi chép số liệu thống kê (trong một số tình huống đơn giản) theo các tiêu chí cho trước.', 'Thu thập, ghi chép số liệu', array['T2.TK.THU-THAP']::text[], false, 113),
  ('T3.TK.BANG', 'toan', 3, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Đọc và mô tả được các số liệu ở dạng bảng.', 'Đọc bảng số liệu', array['T3.TK.THU-THAP']::text[], false, 114),
  ('T3.TK.NHAN-XET', 'toan', 3, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Nêu được một số nhận xét đơn giản từ bảng số liệu.', 'Nhận xét bảng số liệu', array['T3.TK.BANG']::text[], false, 115),
  ('T3.XS.KHA-NANG', 'toan', 3, 'THONG-KE-XAC-SUAT', 'Một số yếu tố xác suất', 'Nhận biết và mô tả được các khả năng xảy ra (có tính ngẫu nhiên) của một sự kiện khi thực hiện (1 lần) thí nghiệm đơn giản (ví dụ: nhận ra được hai khả năng xảy ra đối với mặt xuất hiện của đồng xu khi tung 1 lần; nhận ra được hai khả năng xảy ra đối với màu của quả bóng lấy ra từ hộp kín đựng các quả bóng có hai màu xanh hoặc đỏ;...).', 'Khả năng xảy ra', array['T2.XS.CO-THE']::text[], false, 116),
  ('T4.STN.DOC-VIET', 'toan', 4, 'SO-PHEP-TINH', 'Số tự nhiên', 'Đọc, viết được các số có nhiều chữ số (đến lớp triệu).', 'Đọc, viết số lớp triệu', array['T3.STN.DOC-VIET-100000']::text[], false, 117),
