  ('T4.STN.SO-SANH', 'toan', 4, 'SO-PHEP-TINH', 'Số tự nhiên', 'Nhận biết được cách so sánh hai số trong phạm vi lớp triệu.', 'So sánh số lớp triệu', array['T4.STN.GIA-TRI-CHU-SO', 'T3.STN.SO-SANH']::text[], false, 121),
  ('T4.STN.SAP-XEP', 'toan', 4, 'SO-PHEP-TINH', 'Số tự nhiên', 'Thực hiện được việc sắp xếp các số theo thứ tự (từ bé đến lớn hoặc ngược lại) trong một nhóm có không quá 4 số (trong phạm vi lớp triệu).', 'Sắp xếp số lớp triệu', array['T4.STN.SO-SANH']::text[], false, 122),
  ('T4.STN.LAM-TRON', 'toan', 4, 'SO-PHEP-TINH', 'Số tự nhiên', 'Làm tròn được số đến tròn chục, tròn trăm, tròn nghìn, tròn mười nghìn, tròn trăm nghìn (ví dụ: làm tròn số 12 345 đến hàng trăm thì được số 12 300).', 'Làm tròn số', array['T4.STN.GIA-TRI-CHU-SO', 'T3.STN.LAM-TRON']::text[], false, 123),
  ('T4.PT.CONG-TRU', 'toan', 4, 'SO-PHEP-TINH', 'Các phép tính với số tự nhiên', 'Thực hiện được các phép cộng, phép trừ các số tự nhiên có nhiều chữ số (có nhớ không quá ba lượt và không liên tiếp).', 'Cộng, trừ số nhiều chữ số', array['T3.PT.CONG-TRU-5-CS', 'T4.STN.GIA-TRI-CHU-SO']::text[], false, 124),
