  ('T4.PT.NHAN-CHIA-10', 'toan', 4, 'SO-PHEP-TINH', 'Các phép tính với số tự nhiên', 'Thực hiện được phép nhân với 10; 100; 1000;... và phép chia cho 10; 100; 1000;...', 'Nhân, chia với 10, 100, 1000', array['T4.STN.GIA-TRI-CHU-SO', 'T3.PT.BANG-NHAN-CHIA']::text[], false, 129),
