  ('T4.TN.THUAN-TIEN', 'toan', 4, 'SO-PHEP-TINH', 'Tính nhẩm', 'Vận dụng được tính chất của phép tính để tính nhẩm và tính bằng cách thuận tiện nhất.', 'Tính bằng cách thuận tiện', array['T4.PT.TINH-CHAT-CONG', 'T4.PT.TINH-CHAT-NHAN']::text[], false, 131),
