  ('T4.PS.QUY-DONG', 'toan', 4, 'SO-PHEP-TINH', 'Phân số', 'Thực hiện được việc quy đồng mẫu số hai phân số trong trường hợp có một mẫu số chia hết cho mẫu số còn lại.', 'Quy đồng mẫu số', array['T4.PS.TINH-CHAT']::text[], false, 140),
