  ('T4.PSPT.GIAI-TOAN', 'toan', 4, 'SO-PHEP-TINH', 'Các phép tính với phân số', 'Giải quyết được một số vấn đề gắn với việc giải các bài toán (có đến hai hoặc ba bước tính) liên quan đến 4 phép tính với phân số (ví dụ: bài toán liên quan đến tìm phân số của một số).', 'Giải toán về phân số', array['T4.PSPT.CONG-TRU', 'T4.PSPT.NHAN-CHIA']::text[], false, 145),
