  ('T4.HH.BINH-HANH-THOI', 'toan', 4, 'HINH-DO-LUONG', 'Hình học trực quan', 'Nhận biết được hình bình hành, hình thoi.', 'Hình bình hành, hình thoi', array['T4.HH.VUONG-GOC-SONG-SONG', 'T3.HH.YEU-TO-HINH']::text[], false, 148),
  ('T4.HH.VE-VUONG-GOC', 'toan', 4, 'HINH-DO-LUONG', 'Hình học trực quan', 'Thực hiện được việc vẽ đường thẳng vuông góc, đường thẳng song song bằng thước thẳng và êke.', 'Vẽ đường vuông góc, song song', array['T4.HH.VUONG-GOC-SONG-SONG', 'T3.HH.EKE-COMPA']::text[], false, 149),
