  ('T4.DL.YEN-TA-TAN', 'toan', 4, 'HINH-DO-LUONG', 'Đo lường', 'Nhận biết được các đơn vị đo khối lượng: yến, tạ, tấn và quan hệ giữa các đơn vị đó với kg.', 'Yến, tạ, tấn', array['T3.DL.GAM']::text[], false, 152),
