  ('T4.DL.DUNG-CU', 'toan', 4, 'HINH-DO-LUONG', 'Đo lường', 'Sử dụng được một số dụng cụ thông dụng để thực hành cân, đo, đong, đếm, xem thời gian với các đơn vị đo đã học.', 'Dùng dụng cụ đo', array['T3.DL.DUNG-CU']::text[], false, 156),
  ('T4.DL.DO-GOC', 'toan', 4, 'HINH-DO-LUONG', 'Đo lường', 'Sử dụng được thước đo góc để đo các góc: 60°; 90°; 120°; 180°.', 'Dùng thước đo góc', array['T4.DL.DO']::text[], false, 157),
  ('T4.DL.CHUYEN-DOI', 'toan', 4, 'HINH-DO-LUONG', 'Đo lường', 'Thực hiện được việc chuyển đổi và tính toán với các số đo độ dài (mm, cm, dm, m, km); diện tích (mm², cm², dm², m²); khối lượng (g, kg, yến, tạ, tấn); dung tích (ml, l); thời gian (giây, phút, giờ, ngày, tuần lễ, tháng, năm, thế kỉ); tiền Việt Nam đã học.', 'Đổi và tính số đo', array['T4.DL.YEN-TA-TAN', 'T4.DL.DIEN-TICH', 'T4.DL.GIAY-THE-KI', 'T3.DL.CHUYEN-DOI', 'T4.PT.NHAN-CHIA-10']::text[], false, 158),
  ('T4.DL.UOC-LUONG', 'toan', 4, 'HINH-DO-LUONG', 'Đo lường', 'Thực hiện được việc ước lượng các kết quả đo lường trong một số trường hợp đơn giản (ví dụ: con bò cân nặng khoảng 3 tạ,...).', 'Ước lượng số đo', array['T4.DL.YEN-TA-TAN', 'T3.DL.UOC-LUONG']::text[], false, 159),
  ('T4.DL.THUC-TIEN', 'toan', 4, 'HINH-DO-LUONG', 'Đo lường', 'Giải quyết được một số vấn đề thực tiễn liên quan đến đo độ dài, diện tích, khối lượng, dung tích, thời gian, tiền Việt Nam.', 'Đo lường trong đời sống', array['T4.DL.CHUYEN-DOI']::text[], false, 160),
  ('T4.TK.DAY-SO-LIEU', 'toan', 4, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Nhận biết được về dãy số liệu thống kê.', 'Dãy số liệu thống kê', array['T3.TK.THU-THAP']::text[], false, 161),
  ('T4.TK.SAP-XEP', 'toan', 4, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Nhận biết được cách sắp xếp dãy số liệu thống kê theo các tiêu chí cho trước.', 'Sắp xếp dãy số liệu', array['T4.TK.DAY-SO-LIEU']::text[], false, 162),
  ('T4.TK.DOC-BIEU-DO-COT', 'toan', 4, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Đọc và mô tả được các số liệu ở dạng biểu đồ cột.', 'Đọc biểu đồ cột', array['T3.TK.BANG']::text[], false, 163),
  ('T4.TK.XEP-BIEU-DO-COT', 'toan', 4, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Sắp xếp được số liệu vào biểu đồ cột (không yêu cầu học sinh vẽ biểu đồ).', 'Biểu diễn bằng biểu đồ cột', array['T4.TK.DOC-BIEU-DO-COT']::text[], false, 164),
  ('T4.TK.NHAN-XET', 'toan', 4, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Nêu được một số nhận xét đơn giản từ biểu đồ cột.', 'Nhận xét biểu đồ cột', array['T4.TK.DOC-BIEU-DO-COT']::text[], false, 165),
  ('T4.TK.TRUNG-BINH', 'toan', 4, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Tính được giá trị trung bình của các số liệu trong bảng hay biểu đồ cột.', 'Trung bình các số liệu', array['T4.TK.DOC-BIEU-DO-COT', 'T4.PT.TRUNG-BINH-CONG']::text[], false, 166),
  ('T4.TK.QUY-LUAT', 'toan', 4, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Làm quen với việc phát hiện vấn đề hoặc quy luật đơn giản dựa trên quan sát các số liệu từ biểu đồ cột.', 'Tìm quy luật từ biểu đồ', array['T4.TK.NHAN-XET']::text[], false, 167),
  ('T4.TK.GIAI-QUYET', 'toan', 4, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Giải quyết được những vấn đề đơn giản liên quan đến các số liệu thu được từ biểu đồ cột.', 'Giải toán với biểu đồ cột', array['T4.TK.NHAN-XET', 'T4.TK.TRUNG-BINH']::text[], false, 168),
  ('T4.XS.KIEM-DEM', 'toan', 4, 'THONG-KE-XAC-SUAT', 'Một số yếu tố xác suất', 'Kiểm đếm được số lần lặp lại của một khả năng xảy ra (nhiều lần) của một sự kiện khi thực hiện (nhiều lần) thí nghiệm, trò chơi đơn giản (ví dụ: trong một vài trò chơi như tung đồng xu, lấy bóng từ hộp kín,...).', 'Kiểm đếm số lần xảy ra', array['T3.XS.KHA-NANG']::text[], false, 169),
  ('T5.STN.DOC-VIET-SO-SANH', 'toan', 5, 'SO-PHEP-TINH', 'Số tự nhiên', 'Đọc, viết, so sánh, xếp thứ tự được các số tự nhiên.', 'Đọc, viết, so sánh số', array['T4.STN.SAP-XEP']::text[], false, 170),
  ('T5.STN.BON-PHEP-TINH', 'toan', 5, 'SO-PHEP-TINH', 'Số tự nhiên', 'Thực hiện được các phép tính cộng, trừ, nhân, chia các số tự nhiên.', 'Bốn phép tính số tự nhiên', array['T4.PT.CONG-TRU', 'T4.PT.NHAN-2-CS', 'T4.PT.CHIA-2-CS']::text[], false, 171),
  ('T5.STN.TINH-HOP-LI', 'toan', 5, 'SO-PHEP-TINH', 'Số tự nhiên', 'Vận dụng được tính chất của phép tính với số tự nhiên để tính nhẩm và tính hợp lí.', 'Tính nhẩm, tính hợp lí', array['T5.STN.BON-PHEP-TINH', 'T4.TN.THUAN-TIEN']::text[], false, 172),
  ('T5.STN.UOC-LUONG-LAM-TRON', 'toan', 5, 'SO-PHEP-TINH', 'Số tự nhiên', 'Ước lượng và làm tròn được số trong những tính toán đơn giản.', 'Ước lượng, làm tròn số', array['T4.STN.LAM-TRON', 'T4.TN.UOC-LUONG']::text[], false, 173),
  ('T5.STN.BON-BUOC', 'toan', 5, 'SO-PHEP-TINH', 'Số tự nhiên', 'Giải quyết được vấn đề gắn với việc giải các bài toán có đến bốn bước tính liên quan đến các phép tính về số tự nhiên; liên quan đến quan hệ phụ thuộc trực tiếp và đơn giản.', 'Toán có lời văn 4 bước', array['T5.STN.BON-PHEP-TINH', 'T4.GQ.BA-BUOC']::text[], false, 174),
  ('T5.PS.RUT-GON', 'toan', 5, 'SO-PHEP-TINH', 'Phân số', 'Rút gọn được phân số.', 'Rút gọn phân số', array['T4.PS.RUT-GON']::text[], false, 175),
  ('T5.PS.QUY-DONG-SO-SANH', 'toan', 5, 'SO-PHEP-TINH', 'Phân số', 'Quy đồng, so sánh, xếp thứ tự được các phân số trong trường hợp có một mẫu số chia hết cho các mẫu số còn lại.', 'Quy đồng, so sánh phân số', array['T4.PS.QUY-DONG', 'T4.PS.SO-SANH']::text[], false, 176),
  ('T5.PS.BON-PHEP-TINH', 'toan', 5, 'SO-PHEP-TINH', 'Phân số', 'Thực hiện được phép cộng, phép trừ các phân số trong trường hợp có một mẫu số chia hết cho các mẫu số còn lại và nhân, chia phân số.', 'Cộng, trừ, nhân, chia phân số', array['T4.PSPT.CONG-TRU', 'T4.PSPT.NHAN-CHIA', 'T5.PS.QUY-DONG-SO-SANH']::text[], false, 177),
  ('T5.PS.CONG-KHAC-MAU', 'toan', 5, 'SO-PHEP-TINH', 'Phân số', 'Thực hiện được phép cộng, phép trừ hai phân số bằng cách lấy mẫu số chung là tích của hai mẫu số.', 'Cộng, trừ phân số khác mẫu', array['T4.PS.QUY-DONG', 'T5.PS.BON-PHEP-TINH']::text[], false, 178),
  ('T5.PS.THAP-PHAN-HON-SO', 'toan', 5, 'SO-PHEP-TINH', 'Phân số', 'Nhận biết được phân số thập phân và cách viết phân số thập phân ở dạng hỗn số.', 'Phân số thập phân, hỗn số', array['T4.PS.KHAI-NIEM', 'T4.PT.NHAN-CHIA-10']::text[], false, 179),
  ('T5.PS.GIAI-TOAN', 'toan', 5, 'SO-PHEP-TINH', 'Phân số', 'Giải quyết được vấn đề gắn với việc giải các bài toán (có một hoặc một vài bước tính) liên quan đến các phép tính về phân số.', 'Giải toán về phân số', array['T5.PS.BON-PHEP-TINH', 'T4.PSPT.GIAI-TOAN']::text[], false, 180),
  ('T5.STP.DOC-VIET', 'toan', 5, 'SO-PHEP-TINH', 'Số thập phân', 'Đọc, viết được số thập phân.', 'Đọc, viết số thập phân', array['T5.PS.THAP-PHAN-HON-SO']::text[], false, 181),
  ('T5.STP.CAU-TAO', 'toan', 5, 'SO-PHEP-TINH', 'Số thập phân', 'Nhận biết được số thập phân gồm phần nguyên, phần thập phân và hàng của số thập phân.', 'Hàng của số thập phân', array['T5.STP.DOC-VIET', 'T4.STN.GIA-TRI-CHU-SO']::text[], false, 182),
  ('T5.STP.SO-DO', 'toan', 5, 'SO-PHEP-TINH', 'Số thập phân', 'Thể hiện được các số đo đại lượng bằng cách dùng số thập phân.', 'Số đo dạng số thập phân', array['T5.STP.CAU-TAO', 'T4.DL.CHUYEN-DOI']::text[], false, 183),
  ('T5.STP.SO-SANH', 'toan', 5, 'SO-PHEP-TINH', 'Số thập phân', 'Nhận biết được cách so sánh hai số thập phân.', 'So sánh số thập phân', array['T5.STP.CAU-TAO']::text[], false, 184),
  ('T5.STP.SAP-XEP', 'toan', 5, 'SO-PHEP-TINH', 'Số thập phân', 'Thực hiện được việc sắp xếp các số thập phân theo thứ tự (từ bé đến lớn hoặc ngược lại) trong một nhóm có không quá 4 số thập phân.', 'Sắp xếp số thập phân', array['T5.STP.SO-SANH']::text[], false, 185),
  ('T5.STP.LAM-TRON', 'toan', 5, 'SO-PHEP-TINH', 'Số thập phân', 'Làm tròn được một số thập phân tới số tự nhiên gần nhất hoặc tới số thập phân có một hoặc hai chữ số ở phần thập phân.', 'Làm tròn số thập phân', array['T5.STP.CAU-TAO', 'T4.STN.LAM-TRON']::text[], false, 186),
  ('T5.STPPT.CONG-TRU', 'toan', 5, 'SO-PHEP-TINH', 'Các phép tính với số thập phân', 'Thực hiện được phép cộng, phép trừ hai số thập phân.', 'Cộng, trừ số thập phân', array['T5.STP.CAU-TAO', 'T4.PT.CONG-TRU']::text[], false, 187),
  ('T5.STPPT.NHAN', 'toan', 5, 'SO-PHEP-TINH', 'Các phép tính với số thập phân', 'Thực hiện được phép nhân một số với số thập phân có không quá hai chữ số ở dạng: a,b và 0,ab.', 'Nhân với số thập phân', array['T5.STP.CAU-TAO', 'T4.PT.NHAN-2-CS']::text[], false, 188),
  ('T5.STPPT.CHIA', 'toan', 5, 'SO-PHEP-TINH', 'Các phép tính với số thập phân', 'Thực hiện được phép chia một số với số thập phân có không quá hai chữ số khác không ở dạng: a,b và 0,ab.', 'Chia cho số thập phân', array['T5.STPPT.NHAN', 'T4.PT.CHIA-2-CS']::text[], false, 189),
  ('T5.STPPT.TINH-CHAT', 'toan', 5, 'SO-PHEP-TINH', 'Các phép tính với số thập phân', 'Vận dụng được tính chất của các phép tính với số thập phân và quan hệ giữa các phép tính đó trong thực hành tính toán.', 'Tính chất phép tính thập phân', array['T5.STPPT.CONG-TRU', 'T5.STPPT.NHAN', 'T4.TN.THUAN-TIEN']::text[], false, 190),
  ('T5.STPPT.NHAM-10', 'toan', 5, 'SO-PHEP-TINH', 'Các phép tính với số thập phân', 'Thực hiện được phép nhân, chia nhẩm một số thập phân với (cho) 10; 100; 1000;... hoặc với (cho) 0,1; 0,01; 0,001;...', 'Nhân, chia nhẩm với 10; 0,1', array['T5.STP.CAU-TAO', 'T4.PT.NHAN-CHIA-10']::text[], false, 191),
  ('T5.STPPT.GIAI-TOAN', 'toan', 5, 'SO-PHEP-TINH', 'Các phép tính với số thập phân', 'Giải quyết vấn đề gắn với việc giải các bài toán (có một hoặc một vài bước tính) liên quan đến các phép tính với các số thập phân.', 'Giải toán với số thập phân', array['T5.STPPT.CONG-TRU', 'T5.STPPT.NHAN', 'T5.STPPT.CHIA']::text[], false, 192),
  ('T5.TSPT.NHAN-BIET', 'toan', 5, 'SO-PHEP-TINH', 'Tỉ số. Tỉ số phần trăm', 'Nhận biết được tỉ số, tỉ số phần trăm của hai đại lượng cùng loại.', 'Tỉ số, tỉ số phần trăm', array['T4.PS.KHAI-NIEM', 'T5.PS.THAP-PHAN-HON-SO']::text[], false, 193),
  ('T5.TSPT.TONG-HIEU-TI', 'toan', 5, 'SO-PHEP-TINH', 'Tỉ số. Tỉ số phần trăm', 'Giải quyết được một số vấn đề gắn với việc giải các bài toán liên quan đến: tìm hai số khi biết tổng (hoặc hiệu) và tỉ số của hai số đó.', 'Tìm hai số biết tỉ số', array['T5.TSPT.NHAN-BIET', 'T4.GQ.BA-BUOC']::text[], false, 194),
  ('T5.TSPT.TINH-TI-SO-PT', 'toan', 5, 'SO-PHEP-TINH', 'Tỉ số. Tỉ số phần trăm', 'Giải quyết được một số vấn đề gắn với việc giải các bài toán liên quan đến: tính tỉ số phần trăm của hai số.', 'Tính tỉ số phần trăm', array['T5.TSPT.NHAN-BIET', 'T5.STPPT.CHIA']::text[], false, 195),
  ('T5.TSPT.GIA-TRI-PT', 'toan', 5, 'SO-PHEP-TINH', 'Tỉ số. Tỉ số phần trăm', 'Giải quyết được một số vấn đề gắn với việc giải các bài toán liên quan đến: tìm giá trị phần trăm của một số cho trước.', 'Tìm phần trăm của một số', array['T5.TSPT.NHAN-BIET', 'T5.STPPT.NHAN']::text[], false, 196),
  ('T5.TSPT.TI-LE-BAN-DO', 'toan', 5, 'SO-PHEP-TINH', 'Tỉ số. Tỉ số phần trăm', 'Nhận biết được tỉ lệ bản đồ. Vận dụng được tỉ lệ bản đồ để giải quyết một số tình huống thực tiễn.', 'Tỉ lệ bản đồ', array['T5.TSPT.NHAN-BIET', 'T4.DL.CHUYEN-DOI']::text[], false, 197),
  ('T5.TSPT.MAY-TINH', 'toan', 5, 'SO-PHEP-TINH', 'Tỉ số. Tỉ số phần trăm', 'Làm quen với việc sử dụng máy tính cầm tay để thực hiện các phép tính cộng, trừ, nhân, chia các số tự nhiên; tính tỉ số phần trăm của hai số; tính giá trị phần trăm của một số cho trước.', 'Dùng máy tính cầm tay', array['T5.TSPT.TINH-TI-SO-PT', 'T5.TSPT.GIA-TRI-PT']::text[], false, 198),
  ('T5.HH.HINH-THANG-TAM-GIAC', 'toan', 5, 'HINH-DO-LUONG', 'Hình học trực quan', 'Nhận biết được hình thang, đường tròn, một số loại hình tam giác như tam giác nhọn, tam giác vuông, tam giác tù, tam giác đều.', 'Hình thang, các loại tam giác', array['T4.HH.GOC', 'T4.HH.VUONG-GOC-SONG-SONG']::text[], false, 199),
  ('T5.HH.KHAI-TRIEN', 'toan', 5, 'HINH-DO-LUONG', 'Hình học trực quan', 'Nhận biết được hình khai triển của hình lập phương, hình hộp chữ nhật và hình trụ.', 'Hình khai triển', array['T3.HH.YEU-TO-KHOI']::text[], false, 200),
  ('T5.HH.VE-HINH', 'toan', 5, 'HINH-DO-LUONG', 'Hình học trực quan', 'Vẽ được hình thang, hình bình hành, hình thoi (sử dụng lưới ô vuông).', 'Vẽ hình thang, bình hành, thoi', array['T5.HH.HINH-THANG-TAM-GIAC', 'T4.HH.BINH-HANH-THOI']::text[], false, 201),
  ('T5.HH.DUONG-CAO', 'toan', 5, 'HINH-DO-LUONG', 'Hình học trực quan', 'Vẽ được đường cao của hình tam giác.', 'Vẽ đường cao tam giác', array['T5.HH.HINH-THANG-TAM-GIAC', 'T4.HH.VE-VUONG-GOC']::text[], false, 202),
  ('T5.HH.VE-DUONG-TRON', 'toan', 5, 'HINH-DO-LUONG', 'Hình học trực quan', 'Vẽ được đường tròn có tâm và độ dài bán kính hoặc đường kính cho trước.', 'Vẽ đường tròn', array['T3.HH.EKE-COMPA']::text[], false, 203),
  ('T5.HH.GIAI-QUYET', 'toan', 5, 'HINH-DO-LUONG', 'Hình học trực quan', 'Giải quyết được một số vấn đề về đo, vẽ, lắp ghép, tạo hình gắn với một số hình phẳng và hình khối đã học, liên quan đến ứng dụng của hình học trong thực tiễn, liên quan đến nội dung các môn học như Mĩ thuật, Công nghệ, Tin học.', 'Hình học trong đời sống', array['T5.HH.VE-HINH', 'T5.HH.VE-DUONG-TRON']::text[], false, 204),
  ('T5.DL.KM2-HA', 'toan', 5, 'HINH-DO-LUONG', 'Đo lường', 'Nhận biết được các đơn vị đo diện tích: km² (ki-lô-mét vuông), ha (héc-ta).', 'Ki-lô-mét vuông, héc-ta', array['T4.DL.DIEN-TICH']::text[], false, 205),
  ('T5.DL.THE-TICH', 'toan', 5, 'HINH-DO-LUONG', 'Đo lường', 'Nhận biết được “thể tích” thông qua một số biểu tượng cụ thể.', 'Làm quen thể tích', array['T3.DL.DIEN-TICH']::text[], false, 206),
  ('T5.DL.DON-VI-THE-TICH', 'toan', 5, 'HINH-DO-LUONG', 'Đo lường', 'Nhận biết được một số đơn vị đo thể tích thông dụng: cm³ (xăng-ti-mét khối), dm³ (đề-xi-mét khối), m³ (mét khối).', 'Đơn vị cm³, dm³, m³', array['T5.DL.THE-TICH']::text[], false, 207),
  ('T5.DL.VAN-TOC', 'toan', 5, 'HINH-DO-LUONG', 'Đo lường', 'Nhận biết được vận tốc của một chuyển động đều; tên gọi, kí hiệu của một số đơn vị đo vận tốc: km/h (km/giờ), m/s (m/giây).', 'Vận tốc', array['T4.DL.GIAY-THE-KI']::text[], false, 208),
  ('T5.DL.DUNG-CU', 'toan', 5, 'HINH-DO-LUONG', 'Đo lường', 'Sử dụng được một số dụng cụ thông dụng để thực hành cân, đo, đong, đếm, xem thời gian, mua bán với các đơn vị đo đại lượng và tiền tệ đã học.', 'Dùng dụng cụ đo, mua bán', array['T4.DL.DUNG-CU']::text[], false, 209),
  ('T5.DL.CHUYEN-DOI', 'toan', 5, 'HINH-DO-LUONG', 'Đo lường', 'Thực hiện được việc chuyển đổi và tính toán với các số đo thể tích (cm³, dm³, m³) và số đo thời gian.', 'Đổi số đo thể tích', array['T5.DL.DON-VI-THE-TICH', 'T4.DL.CHUYEN-DOI']::text[], false, 210),
  ('T5.DL.DT-TAM-GIAC-THANG', 'toan', 5, 'HINH-DO-LUONG', 'Đo lường', 'Tính được diện tích hình tam giác, hình thang.', 'Diện tích tam giác, hình thang', array['T5.HH.HINH-THANG-TAM-GIAC', 'T3.DL.DIEN-TICH-HCN', 'T5.HH.DUONG-CAO']::text[], false, 211),
  ('T5.DL.HINH-TRON', 'toan', 5, 'HINH-DO-LUONG', 'Đo lường', 'Tính được chu vi và diện tích hình tròn.', 'Chu vi, diện tích hình tròn', array['T5.HH.HINH-THANG-TAM-GIAC', 'T5.STPPT.NHAN']::text[], false, 212),
  ('T5.DL.HOP-CHU-NHAT', 'toan', 5, 'HINH-DO-LUONG', 'Đo lường', 'Tính được diện tích xung quanh, diện tích toàn phần, thể tích của hình hộp chữ nhật, hình lập phương.', 'Hình hộp chữ nhật, lập phương', array['T5.HH.KHAI-TRIEN', 'T5.DL.DON-VI-THE-TICH', 'T3.DL.DIEN-TICH-HCN']::text[], false, 213),
  ('T5.DL.UOC-LUONG-THE-TICH', 'toan', 5, 'HINH-DO-LUONG', 'Đo lường', 'Thực hiện được việc ước lượng thể tích trong một số trường hợp đơn giản (ví dụ: thể tích của hộp phấn viết bảng,...).', 'Ước lượng thể tích', array['T5.DL.DON-VI-THE-TICH']::text[], false, 214),
  ('T5.DL.THUC-TIEN', 'toan', 5, 'HINH-DO-LUONG', 'Đo lường', 'Giải quyết được một số vấn đề thực tiễn liên quan đến đo thể tích, dung tích, thời gian.', 'Thể tích, thời gian quanh em', array['T5.DL.CHUYEN-DOI']::text[], false, 215),
  ('T5.DL.CHUYEN-DONG', 'toan', 5, 'HINH-DO-LUONG', 'Đo lường', 'Giải quyết được một số vấn đề gắn với việc giải các bài toán liên quan đến chuyển động đều (tìm vận tốc, quãng đường, thời gian của một chuyển động đều).', 'Toán chuyển động đều', array['T5.DL.VAN-TOC', 'T5.STPPT.CHIA']::text[], false, 216),
  ('T5.TK.THU-THAP', 'toan', 5, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Thực hiện được việc thu thập, phân loại, so sánh, sắp xếp số liệu thống kê theo các tiêu chí cho trước.', 'Thu thập, sắp xếp số liệu', array['T4.TK.SAP-XEP']::text[], false, 217),
  ('T5.TK.DOC-QUAT-TRON', 'toan', 5, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Đọc và mô tả được các số liệu ở dạng biểu đồ hình quạt tròn.', 'Đọc biểu đồ quạt tròn', array['T4.TK.DOC-BIEU-DO-COT', 'T5.TSPT.NHAN-BIET']::text[], false, 218),
  ('T5.TK.XEP-QUAT-TRON', 'toan', 5, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Sắp xếp được số liệu vào biểu đồ hình quạt tròn (không yêu cầu học sinh vẽ hình).', 'Đưa số liệu vào quạt tròn', array['T5.TK.DOC-QUAT-TRON']::text[], false, 219),
  ('T5.TK.CHON-BIEU-DIEN', 'toan', 5, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Lựa chọn được cách biểu diễn (bằng dãy số liệu, bảng số liệu, hoặc bằng biểu đồ) các số liệu thống kê.', 'Chọn cách biểu diễn số liệu', array['T5.TK.THU-THAP', 'T4.TK.XEP-BIEU-DO-COT']::text[], false, 220),
  ('T5.TK.NHAN-XET', 'toan', 5, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Nêu được một số nhận xét đơn giản từ biểu đồ hình quạt tròn.', 'Nhận xét biểu đồ quạt tròn', array['T5.TK.DOC-QUAT-TRON']::text[], false, 221),
  ('T5.TK.QUY-LUAT', 'toan', 5, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Làm quen với việc phát hiện vấn đề hoặc quy luật đơn giản dựa trên quan sát các số liệu từ biểu đồ hình quạt tròn.', 'Tìm quy luật từ quạt tròn', array['T5.TK.NHAN-XET']::text[], false, 222),
  ('T5.TK.GIAI-QUYET', 'toan', 5, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Giải quyết được những vấn đề đơn giản liên quan đến các số liệu thu được từ biểu đồ hình quạt tròn.', 'Giải toán với quạt tròn', array['T5.TK.NHAN-XET', 'T5.TSPT.GIA-TRI-PT']::text[], false, 223),
  ('T5.TK.LIEN-HE', 'toan', 5, 'THONG-KE-XAC-SUAT', 'Một số yếu tố thống kê', 'Nhận biết được mối liên hệ giữa thống kê với các kiến thức khác trong môn Toán và trong thực tiễn (ví dụ: số thập phân, tỉ số phần trăm,...).', 'Thống kê và đời sống', array['T5.TK.GIAI-QUYET']::text[], false, 224),
  ('T5.XS.TI-SO', 'toan', 5, 'THONG-KE-XAC-SUAT', 'Một số yếu tố xác suất', 'Sử dụng được tỉ số để mô tả số lần lặp lại của một khả năng xảy ra (nhiều lần) của một sự kiện trong một thí nghiệm so với tổng số lần thực hiện thí nghiệm đó ở những trường hợp đơn giản (ví dụ: sử dụng tỉ số 2/5 để mô tả 2 lần xảy ra khả năng “mặt sấp đồng xu xuất hiện” khi tung đồng xu 5 lần).', 'Tỉ số mô tả khả năng', array['T4.XS.KIEM-DEM', 'T5.TSPT.NHAN-BIET']::text[], false, 225),
