  ('TRUNG-BINH-QUEN-CHIA', 'Tính tổng các số nhưng quên chia cho số các số hạng.', 'Cộng tất cả lại rồi chia cho số các số em nhé!', 'T4.PT.TRUNG-BINH-CONG', null),
  ('DOC-SO-NHAM-LOP', 'Đọc/viết số nhiều chữ số nhầm lớp: thiếu hoặc thừa chữ số 0 ở lớp nghìn, lớp triệu.', 'Tách số thành từng lớp 3 chữ số (triệu – nghìn – đơn vị) rồi mới đọc, viết nhé!', 'T4.STN.DOC-VIET', 'T4.STN.GIA-TRI-CHU-SO'),
  ('GIA-TRI-CHU-SO-NHAM-HANG', 'Nhầm giá trị của chữ số với chính chữ số đó, hoặc xác định sai hàng.', 'Chữ số đứng ở hàng nào thì có giá trị theo hàng đó, em đếm hàng từ phải sang trái nhé!', 'T4.STN.GIA-TRI-CHU-SO', null),
  ('LAM-TRON-CAT-BO', 'Làm tròn bằng cách bỏ bớt chữ số phía sau, không xét chữ số liền sau (≥ 5 thì làm tròn lên).', 'Nhìn chữ số ngay bên phải: từ 5 trở lên thì làm tròn lên nhé!', 'T4.STN.LAM-TRON', null),
  ('LAM-TRON-SAI-HANG', 'Làm tròn đến sai hàng (vd đề hỏi hàng nghìn nhưng làm tròn đến hàng trăm).', 'Gạch chân chữ số ở hàng cần làm tròn trước khi làm em nhé!', 'T4.STN.LAM-TRON', 'T4.STN.GIA-TRI-CHU-SO'),
  ('PS-TU-MAU-NHAM', 'Nhầm tử số với mẫu số (viết số phần được tô ở dưới gạch ngang).', 'Mẫu số (ở dưới) là số phần bằng nhau; tử số (ở trên) là số phần được lấy nhé!', 'T4.PS.KHAI-NIEM', null),
  ('CONG-CUNG-SO-TU-MAU', 'Nghĩ rằng cộng (hoặc trừ) cùng một số vào tử và mẫu thì được phân số bằng nó.', 'Chỉ khi NHÂN hoặc CHIA cả tử và mẫu với cùng một số thì phân số mới không đổi nhé!', 'T4.PS.TINH-CHAT', null),
  ('QUY-DONG-CHI-NHAN-MAU', 'Khi quy đồng chỉ nhân mẫu số, quên nhân tử số với cùng số đó.', 'Mẫu số nhân với số nào thì tử số cũng nhân với số đó em nhé!', 'T4.PS.QUY-DONG', 'T4.PS.TINH-CHAT'),
  ('RUT-GON-CHUA-TOI-GIAN', 'Rút gọn chưa hết: phân số kết quả vẫn còn rút gọn được.', 'Rút gọn xong, em thử xem tử và mẫu còn cùng chia hết cho số nào nữa không nhé!', 'T4.PS.RUT-GON', null),
  ('KHONG-QUY-DONG', 'So sánh hoặc cộng, trừ hai phân số khác mẫu mà không quy đồng (chỉ nhìn tử số).', 'Hai phân số khác mẫu thì quy đồng mẫu số trước rồi mới so sánh, cộng, trừ nhé!', 'T4.PS.SO-SANH', 'T4.PS.QUY-DONG'),
  ('PS-MAU-LON-HON-LON-HON', 'Nghĩ phân số có mẫu số lớn hơn thì lớn hơn (thật ra cùng tử số, mẫu lớn hơn thì phân số bé hơn).', 'Chia cái bánh thành càng nhiều phần thì mỗi phần càng nhỏ đó em!', 'T4.PS.SO-SANH', 'T4.PS.KHAI-NIEM'),
  ('CONG-TU-CONG-MAU', 'Cộng (trừ) tử số với tử số, mẫu số với mẫu số.', 'Cộng hai phân số: đưa về cùng mẫu số, rồi chỉ cộng tử số, giữ nguyên mẫu số nhé!', 'T4.PSPT.CONG-TRU', 'T4.PS.QUY-DONG'),
  ('CHIA-PS-KHONG-DAO', 'Chia hai phân số nhưng nhân với phân số thứ hai (không đảo ngược), hoặc đảo nhầm phân số thứ nhất.', 'Chia cho một phân số là nhân với phân số đảo ngược của phân số THỨ HAI nhé!', 'T4.PSPT.NHAN-CHIA', null),
  ('GOC-TU-NHON-NHAM', 'Nhầm góc tù với góc nhọn (so sánh với góc vuông chưa đúng).', 'Bé hơn góc vuông là góc nhọn, lớn hơn góc vuông là góc tù em nhé!', 'T4.HH.GOC', null),
  ('DOI-DON-VI-SAI-HE-SO', 'Đổi đơn vị đo dùng sai hệ số (vd 1 tạ = 10 kg, 3 m 5 cm = 3,5 m).', 'Em viết lại bảng đơn vị đo và nhớ mỗi đơn vị gấp bao nhiêu lần đơn vị liền sau nhé!', 'T4.DL.CHUYEN-DOI', 'T4.DL.YEN-TA-TAN'),
  ('DIEN-TICH-HE-SO-10', 'Nghĩ hai đơn vị đo diện tích liền nhau hơn kém 10 lần (thật ra là 100 lần).', 'Đơn vị diện tích liền nhau gấp nhau 100 lần đó em!', 'T4.DL.DIEN-TICH', null),
  ('BIEU-DO-DOC-NHAM', 'Đọc nhầm cột hoặc nhầm vạch chia trên biểu đồ (lấy giá trị thấp nhất thay vì cao nhất, đọc % thành số lượng…).', 'Dò theo đỉnh cột sang trục số bên trái để đọc đúng giá trị nhé!', 'T4.TK.DOC-BIEU-DO-COT', null),
  ('SO-SANH-STP-THEO-DO-DAI', 'So sánh số thập phân theo độ dài phần thập phân như số tự nhiên (nghĩ 0,25 > 0,3 vì 25 > 3).', 'So sánh từng hàng từ trái sang phải: hàng phần mười trước, rồi mới tới hàng phần trăm nhé!', 'T5.STP.SO-SANH', 'T5.STP.CAU-TAO'),
  ('STP-KHONG-THANG-DAU-PHAY', 'Đặt tính cộng, trừ số thập phân không thẳng dấu phẩy (thẳng chữ số cuối).', 'Đặt các dấu phẩy thẳng cột với nhau rồi mới tính em nhé!', 'T5.STPPT.CONG-TRU', 'T5.STP.CAU-TAO'),
  ('STP-NHAN-SAI-DAU-PHAY', 'Đặt dấu phẩy ở tích sai (đếm sai tổng số chữ số ở phần thập phân của các thừa số).', 'Đếm xem hai thừa số có tất cả mấy chữ số ở phần thập phân, rồi tách ở tích bấy nhiêu chữ số nhé!', 'T5.STPPT.NHAN', null),
  ('NHAN-10-THEM-0-STP', 'Nhân số thập phân với 10, 100… bằng cách viết thêm chữ số 0 vào cuối (thay vì dời dấu phẩy).', 'Nhân với 10, 100 thì dời dấu phẩy sang phải 1, 2 chữ số em nhé!', 'T5.STPPT.NHAM-10', 'T5.STP.CAU-TAO'),
  ('PHAN-TRAM-QUEN-NHAN-100', 'Tính thương của hai số nhưng quên nhân với 100 để ra tỉ số phần trăm.', 'Tìm thương rồi nhân với 100 và viết thêm kí hiệu % nhé!', 'T5.TSPT.TINH-TI-SO-PT', null),
  ('PHAN-TRAM-CONG-THANG', 'Cộng/trừ trực tiếp số phần trăm với số đã cho (vd 20% của 150 = 170 hoặc 130).', 'Tìm 20% của 150 là lấy 150 chia 100 rồi nhân 20 em nhé!', 'T5.TSPT.GIA-TRI-PT', null),
  ('DT-TAM-GIAC-QUEN-CHIA-2', 'Tính diện tích tam giác bằng đáy nhân chiều cao, quên chia 2.', 'Diện tích tam giác bằng đáy nhân chiều cao rồi chia 2 nhé!', 'T5.DL.DT-TAM-GIAC-THANG', null),
  ('CHU-VI-DIEN-TICH-NHAM', 'Nhầm công thức chu vi với diện tích (cộng các cạnh khi cần nhân, hoặc ngược lại).', 'Chu vi là đi một vòng quanh hình (cộng các cạnh); diện tích là phần mặt bên trong nhé!', 'T3.DL.CHU-VI', null),
  ('TONG-HIEU-NHAM-SO', 'Bài toán tổng – hiệu: lấy (tổng + hiệu) : 2 nhưng gán kết quả cho số bé, hoặc quên chia 2.', '(Tổng + hiệu) : 2 là số LỚN, (tổng − hiệu) : 2 là số BÉ — em thử lại xem tổng có đúng không nhé!', 'T4.GQ.BA-BUOC', 'T4.PT.CONG-TRU'),
  ('PHUT-THANH-THAP-PHAN', 'Đổi thời gian sai: viết 2 giờ 30 phút thành 2,3 giờ (1 giờ = 60 phút, không phải 100 phút).', '1 giờ có 60 phút, nên 30 phút là nửa giờ = 0,5 giờ em nhé!', 'T5.DL.CHUYEN-DONG', 'T5.DL.CHUYEN-DOI')
